{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 조례상 대중교통과 연계하여 자전거를 이용하는 자에 대한 마일리지 등 인센티브 제공 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 자전거이용 활성화에 관한 조례 제15조제3항제1호는 지하철·버스 등 대중교통과 연계하여 자전거를 이용하는 자를 시장이 마일리지 등 인센티브를 제공할 수 있는 대상으로 정하고 있다. 따라서 대중교통과 함께 자전거를 이용하는 경우 인센티브 제공 대상에 해당할 수 있다. 다만 실제 제공 여부와 내용은 시장이 예산의 범위에서 정하므로, 구체적인 혜택의 종류·금액·신청 방법 등은 이 조례로 직접 정해지지 않는다.",
          "b_ids": "자전거:제15조제3항, 자전거:제15조제3항제1호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
